select count(1)
from inv_transfer_receipt_discrepancy_case c
inner join inv_transfer_order o
        on o.transfer_id = c.transfer_id
where c.discrepancy_case_id = #{caseId}
  and (
      coalesce(nullif(o.from_warehouse_id, 0), o.from_dept_id)
      in

          #{deptId}

      or coalesce(nullif(o.to_warehouse_id, 0), o.to_dept_id)
      in

          #{deptId}

  )

mapper.update:
update inv_transfer_receipt_discrepancy_adjudication_action
set execution_status = #{execution.actionStatusAfter},
    execution_version = #{execution.executionVersionAfter},
    execution_effect_reference = #{execution.effectReference}
where adjudication_action_id = #{execution.actionId}
  and adjudication_id = #{execution.adjudicationId}
  and discrepancy_case_id = #{execution.caseId}
  and execution_status = #{execution.actionStatusBefore}
  and execution_version = #{execution.executionVersionBefore}
  and (
      (#{execution.command} = 'dispatch'
       and execution_effect_reference is null)
      or
      (#{execution.command} = 'complete'
       and execution_effect_reference =
           #{execution.effectReference})
  )
  and exists (
      select 1
      from inv_transfer_receipt_discrepancy_adjudication_execution_event event
      where event.request_id = #{execution.requestId}
        and event.adjudication_action_id =
            #{execution.actionId}
        and event.event_fingerprint =
            #{execution.eventFingerprint}
        and event.action_version_before =
            #{execution.executionVersionBefore}
        and event.action_version_after =
            #{execution.executionVersionAfter}
  )

update inv_transfer_receipt_discrepancy_adjudication
set plan_status = #{execution.planStatusAfter}
where adjudication_id = #{execution.adjudicationId}
  and discrepancy_case_id = #{execution.caseId}
  and decision_fingerprint = #{execution.decisionFingerprint}
  and plan_status = #{execution.planStatusBefore}
  and exists (
      select 1
      from inv_transfer_receipt_discrepancy_adjudication_execution_event event
      where event.request_id = #{execution.requestId}
        and event.adjudication_id = #{execution.adjudicationId}
        and event.event_fingerprint =
            #{execution.eventFingerprint}
        and event.plan_status_before =
            #{execution.planStatusBefore}
        and event.plan_status_after =
            #{execution.planStatusAfter}
  )

update inv_transfer_receipt_discrepancy_case
set status = #{execution.caseStatusAfter},
    case_version = #{execution.caseVersionAfter}
where discrepancy_case_id = #{execution.caseId}
  and case_version = #{execution.caseVersionBefore}
  and status = #{execution.caseStatusBefore}
  and exists (
      select 1
      from inv_transfer_receipt_discrepancy_adjudication_execution_event event
      where event.request_id = #{execution.requestId}
        and event.discrepancy_case_id = #{execution.caseId}
        and event.event_fingerprint =
            #{execution.eventFingerprint}
        and event.case_version_before =
            #{execution.caseVersionBefore}
        and event.case_version_after =
            #{execution.caseVersionAfter}
  )
